// Раскладка клавиатуры МС7004 (копия DEC LK201) для клавиатуры хоста.
//
// Слева клавиша хоста, справа КОД КЛАВИШИ LK201, который МС7004 шлёт
// терминалу. Символ из кода делает терминал: КСМ ищет его в таблице своего
// ПЗУ (0AFD + ~код), РУС/ЛАТ и регистр - тоже его забота, поэтому у
// клавиатуры use_remap = 0.
//
// Латинские буквы отданы клавишам с той же ЛАТИНСКОЙ надписью. На МС7004
// латиница стоит на клавишах ЙЦУКЕН (J на месте Q, C на месте W), поэтому в
// латинском регистре хост печатает то, что на нём написано, а в русском
// получается ЙЦУКЕН самой МС7004. Коды сняты с таблицы ПЗУ КСМ.
//
// Пометка `+shift` - знак набирается с ВР (Shift), `-shift` - без него, хотя
// Shift хоста нажат. Без пометки Shift хоста просто прижимает ВР: так у букв
// меняется регистр (КСМ по ВР делает из заглавной латинской строчную).

// --- Буквы ------------------------------------------------------------
A:      $D2
B:      $E8
C:      $C6
D:      $EC
E:      $D7
F:      $C2
G:      $E1
H:      $F6
I:      $D9
J:      $C1
K:      $D1
L:      $E7
M:      $D3
N:      $DC
O:      $E2
P:      $D8
Q:      $C3
R:      $DD
S:      $CE
T:      $DE
U:      $CC
V:      $F2
W:      $CD
X:      $E3
Y:      $C7
Z:      $F0
[:      $E6     // Ш
]:      $EB     // Щ
\:      $FB     // Э
^:      $C8     // Ч
@:      $ED     // Ю
_:      $F1     // Ъ
{:      $E6 +shift
}:      $EB +shift
bar:    $FB +shift

// --- Цифры и знаки ------------------------------------------------------
// КСМ получает знак верхнего регистра цифр и знаков разрядом 4: `1` и ВР
// дают `!`, `;` и ВР - `+`
1:      $C0 -shift
2:      $C5 -shift
3:      $CB -shift
4:      $D0 -shift
5:      $D6 -shift
6:      $DB -shift
7:      $E0 -shift
8:      $E5 -shift
9:      $EA -shift
0:      $EF
!:      $C0 +shift
":      $C5 +shift
#:      $CB +shift
$:      $D0 +shift
%:      $D6 +shift
&:      $DB +shift
':      $E0 +shift
(:      $E5 +shift
):      $EA +shift
;:      $BF -shift
+:      $BF +shift
colon:  $FA -shift
*:      $FA +shift
-:      $F9 -shift
=:      $F9 +shift
,:      $F3 -shift
<:      $F3 +shift
.:      $F7 -shift
>:      $F7 +shift
/:      $CA -shift
?:      $CA +shift

// --- Управляющие ------------------------------------------------------
space:  $D4
ret:    $BD     // ВК
enter:  $BD
back:   $BC     // ЗБ, код 177
del:    $BC
tab:    $BE
esc:    $71     // Ф11 (АР2) - ESC
up:     $AA
down:   $A9
right:  $A8
left:   $A7

// --- Регистровые ------------------------------------------------------
shift:  $AE     // ВР
ctrl:   $AF     // СУ
caps:   $B0     // ФКС
alt:    $B2     // РУС/ЛАТ

// --- Функциональные ---------------------------------------------------
// F1-F4 - ПФ1-ПФ4 цифрового блока (ESC P, Q, R, S), с ними работают
// редакторы. Клавиши Ф1-Ф5 самой МС7004 - управление терминалом, им отданы
// F5-F9
f1:     $A1     // ПФ1
f2:     $A2     // ПФ2
f3:     $A3     // ПФ3
f4:     $A4     // ПФ4
f5:     $56     // СТОП КАДР
f6:     $57     // ПЕЧАТЬ КАДРА
f7:     $58     // ПАУЗА
f8:     $59     // УСТ РЕЖИМА
f9:     $5A     // Ф5
f10:    $68     // ВЫХОД
